    /// <summary>You, controlled, at (1, 0); a static zombie at (zx, zy).</summary>
    public static SimState fight(List<string> map)
    {
        var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = map.map((row) => row.replace("z", ".")) });
        var y = map.findIndex((row) => row.includes("z"));
        Commands.applyCommand(state, new Command { type = "spawnZombie", x = Js.I(Js.NN(Js.Get(map, y)).indexOf("z")), y = Js.I(y) });
        Js.NN(Js.Get(state.zombies, 0)).kind = "static";
        Commands.applyCommand(state, new Command { type = "takeControl", survivorId = Js.NN(Js.Get(state.survivors, 0)).id });
        return state;
    }

    /// <summary>fights you can read</summary>
    public class D001_fights_you_can_read
    {

        [Fact(DisplayName = "fights you can read > a zombie winds up before it bites, and the bite lands WINDUP_TICKS later")]
        public void T002_a_zombie_winds_up_before_it_bites_and_the_bite_lands_WINDUP_()
        {
            var state = fight([".sz.."]);
            var s = Js.NN(Js.Get(state.survivors, 0));
            Tick.tick(state);
            expect(Js.NN(Js.Get(state.zombies, 0)).windup).toBe(Zombies.WINDUP_TICKS);
            for (var t = 1; t < Zombies.WINDUP_TICKS; t++)
            {
                Tick.tick(state);
            }
            expect(s.health).toBe(1000);
            Tick.tick(state);
            expect(s.health).toBeLessThan(1000);
        }

        [Fact(DisplayName = "fights you can read > step out of reach mid-windup and the bite closes on air")]
        public void T003_step_out_of_reach_mid_windup_and_the_bite_closes_on_air()
        {
            var state = fight(["..sz...."]);
            var s = Js.NN(Js.Get(state.survivors, 0));
            Tick.tick(state);
            Tick.tick(state);
            s.pos = new Point { x = Js.I(0), y = Js.I(0) };
            s.at = Motion.centre(s.pos);
            Tick.tick(state);
            expect(Js.NN(Js.Get(state.zombies, 0)).windup).toBe(0);
            expect(s.health).toBe(1000);
        }

        [Fact(DisplayName = "fights you can read > your blow staggers it and shoves it back: no bite while it reels")]
        public void T004_your_blow_staggers_it_and_shoves_it_back_no_bite_while_it_re()
        {
            var state = fight([".sz..."]);
            var s = Js.NN(Js.Get(state.survivors, 0));
            var z = Js.NN(Js.Get(state.zombies, 0));
            z.health = 1000;
            z.maxHealth = 1000;
            var x = z.at.x;
            var before = z.health;
            expect(Commands.applyCommand(state, new Command { type = "swing", x = Js.I(2), y = Js.I(0) }).ok).toBe(true);
            expect(z.health).toBeLessThan(before);
            expect(z.at.x).toBeGreaterThan(x);
            expect(z.staggerUntil).toBe(state.tick + Zombies.STAGGER_TICKS);
            for (var t = 0; t < Zombies.STAGGER_TICKS; t++)
            {
                Tick.tick(state);
            }
            expect(s.health).toBe(1000);
            expect(Js.NN(state.control).swungTick).toBe(0);
        }

        [Fact(DisplayName = "fights you can read > the dead within reach drag at you")]
        public void T005_the_dead_within_reach_drag_at_you()
        {
            var free = fight(["z.....", ".s...."]);
            free.zombies = [];
            var held = fight([".z....", ".s...."]);
            int moved(SimState state)
            {
                var s = Js.NN(Js.Get(state.survivors, 0));
                var x = s.at.x;
                Commands.applyCommand(state, new Command { type = "steer", dx = 1, dy = 0 });
                Tick.tick(state);
                return s.at.x - x;
            }
            var walk = JsMath.round(((double)(Motion.SUB) / (Survivors.stepPace(free, Js.NN(Js.Get(free.survivors, 0)), Js.NN(Js.Get(free.survivors, 0)).pos))));
            expect(moved(free)).toBe(walk);
            expect(moved(held)).toBe(JsMath.round(((double)((walk * JsMath.max(ControlMod.CLUTCHED_MIN, 100 - ControlMod.CLUTCH_PCT))) / (100))));
        }

        [Fact(DisplayName = "fights you can read > you look where you aim: walking does not turn you, and a swing lands in the arc round your aim")]
        public void T006_you_look_where_you_aim_walking_does_not_turn_you_and_a_swing()
        {
            var state = fight([".....", ".s...", "..z.."]);
            var c = Js.NN(state.control);
            expect(Commands.applyCommand(state, new Command { type = "aim", x = Js.I(45), y = Js.I(45) }).ok).toBe(true);
            expect(c.facing).toEqual(Js.Obj(("x", (object?)(1)), ("y", (object?)(1))));
            expect(Commands.applyCommand(state, new Command { type = "aim", x = Js.I(99), y = Js.I(0) }).ok).toBe(false);
            expect(Commands.applyCommand(state, new Command { type = "aim", x = Js.I(0), y = Js.I(0) }).ok).toBe(false);
            Commands.applyCommand(state, new Command { type = "steer", dx = -1, dy = 0 });
            Tick.tick(state);
            expect(c.facing).toEqual(Js.Obj(("x", (object?)(1)), ("y", (object?)(1))));
            Commands.applyCommand(state, new Command { type = "steer", dx = 0, dy = 0 });
            var z = Js.NN(Js.Get(state.zombies, 0));
            z.health = z.maxHealth = 1000;
            var s = Js.NN(Js.Get(state.survivors, 0));
            s.at = Motion.centre(new Point { x = Js.I(1), y = Js.I(1) });
            s.pos = new Point { x = Js.I(1), y = Js.I(1) };
            z.at = Motion.centre(new Point { x = Js.I(2), y = Js.I(1) });
            z.pos = new Point { x = Js.I(2), y = Js.I(1) };
            Commands.applyCommand(state, new Command { type = "aim", x = Js.I(-64), y = Js.I(0) });
            Js.NN(state.control).nextSwing = 0;
            var away = z.health;
            Commands.applyCommand(state, new Command { type = "swing", x = Js.I(0), y = Js.I(1) });
            expect(z.health).toBe(away);
            Commands.applyCommand(state, new Command { type = "aim", x = Js.I(64), y = Js.I(0) });
            Js.NN(state.control).nextSwing = 0;
            Commands.applyCommand(state, new Command { type = "swing", x = Js.I(2), y = Js.I(1) });
            expect(z.health).toBeLessThan(away);
        }
